maf = sys.argv[2]
out = sys.argv[3]

syn_chr = list(pd.read_csv(syn, sep='\t', header=None)[1])

def a_not_in_b(a, b):
    """
    Determine what values in set a are not in set b
    """
    not_in_b = set(a) - set(b)
    return not_in_b #This will show elements in 'a' that are not in 'b'

#Test a_not_in_b
a = ["1", "2", "3", "4"]
b = ["3", "4", "5", "6"]
c = [ "3", "4"]
a_not_in_b(a, b) #{'1', '2'}
a_not_in_b(c, b) #set()

def is_syntetic(block_lines, syn_chr):
    """
    Determine if chromosomes in a block are all syntetic chromosomes
    """
    sequence_lines = block_lines[1:-1]
    chrom = []
    for s in sequence_lines:
        chrom.append(s.split("\t")[1].split(".")[1])
    not_syn = a_not_in_b(chrom, syn_chr)
    if len(not_syn) == 0:
        syntetic = True
    else:
        syntetic = False
    return syntetic

